# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- A claim with a negative amount is a correction: it names, by number, a SETTLED claim of the
-- same person that it corrects. Null for any other claim.
ALTER TABLE claim ADD COLUMN corrects BIGINT;

-- The amount may now be negative, but only on a correction. Its old CHECK (amount >= 0) has a
-- generated name, so the column is replaced (dropping it drops that check) and copied over.
ALTER TABLE claim ADD COLUMN amount_signed DECIMAL(12, 2);
UPDATE claim SET amount_signed = amount;
ALTER TABLE claim DROP COLUMN amount;
ALTER TABLE claim ALTER COLUMN amount_signed RENAME TO amount;
ALTER TABLE claim ALTER COLUMN amount SET NOT NULL;
ALTER TABLE claim ADD CONSTRAINT claim_amount_correction CHECK (amount >= 0 OR corrects IS NOT NULL);
-- A statement taken of a person: their due-total then (two decimals, or n/a), how many of their
-- claims counted, and the sheet's today when it was taken. A person's statements are in the order
-- of their ids; the last one is the person's last statement.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    taken_on  DATE         NOT NULL,
    due_total VARCHAR(20)  NOT NULL,
    claims    INT          NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);

-- Whether the claim is bound by its person's last statement, and the due it was bound to (null when
-- it had none then: n/a). A bound claim shows and totals that due until the next statement.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);

    /** The rate step: the amount at the percent, to two decimals rounded as a claim rounding by the date does. */
    public BigDecimal rateStep(BigDecimal amount, BigDecimal pct, LocalDate roundingDate) {
        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding(roundingDate));
    }

    /**
     * The late charge on a figure of an OPEN claim dated {@code date}: the late percent of the figure for every full
     * 30 days the sheet's today is past the claim's due-by, rounded as the claim's date has it; zero when not overdue,
     * null (n/a) when the figure is.
     */
    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
        if (figure == null) {
            return null;
        }
        long overdueDays = ChronoUnit.DAYS.between(dueBy, today);
        long periods = overdueDays <= 0 ? 0 : overdueDays / 30;
        return figure.multiply(latePct).multiply(BigDecimal.valueOf(periods)).movePointLeft(2)
                .setScale(2, rounding(date));
    }

    /** The figure with its late charge added on top when the claim is OPEN; null (n/a) stays null. */
    public BigDecimal withLateCharge(BigDecimal figure, boolean open, LocalDate dueBy, LocalDate date) {
        return figure == null || !open ? figure : figure.add(lateCharge(figure, dueBy, date));
    }

    /** A live due raised to the floor; null (n/a) stays null. */
    public BigDecimal floored(BigDecimal due) {
        return due == null ? null : due.max(floor);
    }
}
